/// <summary>
/// Mapping of cost centre dimenion to InventLocation default dimension
/// </summary>
/// <param name = "_entityCtx">Entity buffer</param>
/// <param name = "_dataSourceCtx">Datasource buffer</param>
public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    next mapEntityToDataSource(_entityCtx, _dataSourceCtx);

    if (_dataSourceCtx.name() == dataEntityDataSourceStr(InventWarehouseEntity, InventLocation))
    {
        InventWarehouseEntity entityBuffer = _entityCtx.getEntityRecord();
        InventLocation  inventLocation = _dataSourceCtx.getBuffer();

        DimensionAttribute dimAttribute = DimensionAttribute::findByName(METConstants::costCenter);

        switch (_entityCtx.getDatabaseOperation())
        {
            case DataEntityDatabaseOperation::Insert:

                if (dimAttribute.RecId)
                {
                    DimensionAttributeValueSetStorage setStorageInsert = new DimensionAttributeValueSetStorage();
                    DimensionAttributeValue attributeValue = DimensionAttributeValue::findByDimensionAttributeAndValue(dimAttribute, entityBuffer.METCostCentre, false, true);

                    if (attributeValue.RecId)
                    {
                        setStorageInsert.addItem(attributeValue);
                        inventLocation.METDefaultDimension = LedgerDimensionDefaultFacade::serviceMergeDefaultDimensions(setStorageInsert.save(), inventLocation.METDefaultDimension);
                    }
                }
                break;
            case DataEntityDatabaseOperation::Update:

                if (dimAttribute.RecId)
                {
                    DimensionAttributeValueSetStorage setStorageUpd = DimensionAttributeValueSetStorage::find(inventLocation.METDefaultDimension);
                    DimensionAttributeValue attributeValue = DimensionAttributeValue::findByDimensionAttributeAndValue(dimAttribute, entityBuffer.METCostCentre, false, true);

                    if (attributeValue.RecId)
                    {
                        setStorageUpd.addItem(attributeValue);
                        inventLocation.METDefaultDimension = LedgerDimensionDefaultFacade::serviceMergeDefaultDimensions(setStorageUpd.save(), inventLocation.METDefaultDimension);
                    }
                }
                break;
        }
    }
}

/// <summary>
/// Mapping of unmapped field cost center
/// </summary>
public void postLoad()
{
    next postLoad();

    DefaultDimensionView defaultDimensionView;

    select firstonly displayValue from defaultDimensionView
        where defaultDimensionView.DefaultDimension == InventLocation::find(this.WarehouseId).METDefaultDimension
            && defaultDimensionView.Name == METConstants::costCenter;

    this.METCostCentre = defaultDimensionView.DisplayValue;
}
